insert into public.content (course_id, id, tier, data) values ('ai-eng', 'meta:catalog', 'public', '[{"id":"llm","block":"b1","title":"LLM Fundamentals","tag":"Tokens, context, sampling, model families: the vocabulary layer","why":"Every AI system you''ll oversee sits on top of an LLM API. If you aren''t fluent in tokens, context windows, sampling, and model families, you can''t make a sound call on cost, latency, or quality.","isNew":false,"isUpd":false,"estMin":35},{"id":"prompt","block":"b1","title":"Prompt Engineering","tag":"The cheapest, fastest quality lever you own","why":"Prompt changes are free, instant, and routinely worth 10–30 points of task accuracy. Pull this lever first, before you fine-tune, switch models, or add complexity.","isNew":false,"isUpd":false,"estMin":30},{"id":"context","block":"b1","title":"Context Engineering","tag":"Curating what the model sees: the discipline that ate prompt engineering","why":"The 2025–26 consensus is that managing WHAT goes into the window matters more than wordsmithing instructions. Agents, RAG, memory, and harnesses are all context engineering problems. Prompt engineering isn''t irrelevant; clear instructions still matter. But in agentic systems, what the model sees outweighs how it''s phrased. Prompt engineering designs the instructions. Context engineering decides what else is in the room when the model reads them.","isNew":false,"isUpd":false,"estMin":30},{"id":"landscape","block":"b1","title":"2026 Model Landscape","tag":"Who''s who as of Aug 9, 2026, and how to choose","why":"Model choice is the highest-impact cost and quality decision on any AI project. The lineup shifts quarterly. The decision framework doesn''t.","isNew":true,"isUpd":false,"estMin":25},{"id":"rag","block":"b2","title":"RAG Systems & Pipelines","tag":"The dominant production pattern for grounding models in your data","why":"RAG is still the best way to make a model answer from YOUR knowledge with citations, freshness, and access control. Fine-tuning and long context alone give you none of those.","isNew":false,"isUpd":false,"estMin":40},{"id":"embed","block":"b2","title":"Embeddings","tag":"Meaning as geometry: the substrate under retrieval","why":"Embeddings power retrieval, dedup, clustering, recommendation, and semantic caching. Choosing them well and running them well is the foundation under every RAG and memory system.","isNew":false,"isUpd":false,"estMin":30},{"id":"vecdb","block":"b2","title":"Vector Databases","tag":"Approximate search at scale, and when you don''t need one","why":"The vector DB you pick locks in cost, latency, scale ceiling, and operational burden for every retrieval-backed feature. Getting it wrong hurts both ways: overkill wastes money, underkill caps you.","isNew":false,"isUpd":false,"estMin":30},{"id":"memory","block":"b2","title":"Memory Systems","tag":"State across the stateless: sessions, users, agents","why":"The model forgets everything between calls. Every product experience of ''it remembers me'', and every agent that survives a long task, is a memory system you engineered and own.","isNew":false,"isUpd":false,"estMin":30},{"id":"agents","block":"b3","title":"AI Agents","tag":"LLMs in a loop with tools: capable, over-applied, and dependent on the harness","why":"Agents are the pattern everyone reaches for right now, and the one people misuse most. Knowing when a plain workflow beats an agent, and what actually makes agents reliable, is senior-level judgment.","isNew":false,"isUpd":false,"estMin":35},{"id":"tools","block":"b3","title":"Tool / Function Calling","tag":"The hands of the model: API design for a probabilistic caller","why":"Tool calling is how models reach into the world. Most so-called agent bugs are really tool-design bugs: vague descriptions, leaky abstractions, errors that explain nothing.","isNew":false,"isUpd":false,"estMin":30},{"id":"harness","block":"b3","title":"Agent Harnesses","tag":"The scaffolding around the model: 2026''s defining layer","why":"The same model scores wildly differently depending on its harness. In Princeton HAL''s CORE-Bench evaluations (Dec 2025), Claude Opus 4.5 scored ~78% under a Claude Code-based scaffold versus 42% under the generic CORE-Agent scaffold, a ~36-point gap from the same model. Anthropic''s own Opus 4.8 release confirmed the pattern: Terminal-Bench scores differ significantly depending on which harness you use. In 2026, harness engineering is AI engineering. It''s where capability actually comes from.","isNew":true,"isUpd":false,"estMin":40},{"id":"multi","block":"b3","title":"Multi-Agent Systems","tag":"When one context window isn''t enough, and the coordination tax that follows","why":"Multi-agent works well for parallelizable, context-heavy jobs and wastes money everywhere else. The skill is telling the two apart and paying the coordination tax only when it buys you something.","isNew":false,"isUpd":false,"estMin":30},{"id":"design","block":"b4","title":"AI System Design","tag":"The full production stack around the model call","why":"The model call is 5% of the system. Gateways, caching, queues, fallbacks, observability, and cost controls are the other 95%, and they''re what page you at 3am.","isNew":false,"isUpd":false,"estMin":40},{"id":"evals","block":"b4","title":"Evaluation & Eval Harnesses","tag":"The discipline that separates shipping from guessing","why":"Probabilistic systems can''t be unit-tested into correctness. Evals are how you know quality went up, catch regressions before users do, and ship prompt or model changes with evidence. Teams without evals are flying IFR with no instruments.","isNew":false,"isUpd":true,"estMin":40},{"id":"halluc","block":"b4","title":"Hallucination & Guardrails","tag":"Confidently wrong: engineering around the failure mode that erodes trust","why":"Hallucination is intrinsic to next-token prediction. The model is rewarded for sounding fluent, not for being true. One confidently wrong answer in a legal, medical, or financial flow can erase the product''s credibility. You can''t eliminate it, so you have to engineer around it.","isNew":false,"isUpd":false,"estMin":35},{"id":"lead","block":"b4","title":"Leadership Playbook","tag":"Judgment, communication, and the meta-skill of staying current","why":"Past senior level, your value comes from decisions and narratives: which bets to make, what to tell executives, how to grow a team''s AI judgment. Technical depth is the entry fee. This is the differentiator.","isNew":false,"isUpd":false,"estMin":35},{"id":"finetune","block":"b5","title":"Fine-Tuning & Alignment Mechanics","tag":"When to reshape weights vs when to reshape prompts, and how not to wreck the model","why":"At volume, fine-tuning buys you unit economics and behavioral consistency that prompting can''t reach. A mis-scoped fine-tune does the opposite: it destroys general capabilities, quietly inflates eval scores, and costs you weeks to recover from. Staff-level judgment is knowing when the math works, and knowing when to stop before the damage compounds.","isNew":false,"isUpd":false,"estMin":50},{"id":"aisec","block":"b5","title":"AI Security & Adversarial Robustness","tag":"New attack surfaces, new attack classes: engineering a system that holds under adversarial pressure","why":"Every LLM feature you ship is a new attack surface. Prompt injection, jailbreaks, and supply-chain attacks buried in tool results are production incident classes, not theoretical worries. The threat model, the pre-launch red-team, and the defense architecture all land on the staff engineer, because no amount of vendor alignment makes a system safe without the structural controls you design yourself.","isNew":false,"isUpd":false,"estMin":45},{"id":"mlops","block":"b5","title":"AI Observability & Production Reliability","tag":"Distributed tracing, quality SLOs, and drift detection: the instrumentation layer you build before the first incident","why":"AI systems fail silently. Wrong answers come back with 200 OK. Quality drifts over weeks while the dashboards stay green. Costs run away without ever tripping an error budget. Standard APM is necessary but nowhere near sufficient. Staff engineers design the observability architecture before the system ships, because retrofitting it after the first quality incident always costs more than building it in.","isNew":false,"isUpd":false,"estMin":45},{"id":"dataeng","block":"b5","title":"Data Engineering for AI Systems","tag":"The pipeline that sets your retrieval ceiling: chunking, embedding lifecycle, and the data flywheel","why":"The model and the retrieval system are only as good as the data pipeline feeding them. Bad chunking, mixed embedding versions, stale ACLs, and missing re-indexing triggers quietly cap quality at 60–70% before you write a single prompt. Staff engineers design the data architecture so the retrieval system improves on its own over time, instead of needing a manual tune-up every quarter.","isNew":false,"isUpd":false,"estMin":45},{"id":"multimodal","block":"b5","title":"Multimodal Systems & Document Intelligence","tag":"Vision-language pipelines, document ingestion at scale, and when to pay for vision vs when to skip it","why":"Enterprise document workflows (insurance claims, legal filings, financial reports, technical manuals) are full of tables, figures, and scanned content that text-only pipelines handle badly. Building multimodal document intelligence that stays reliable at scale means knowing when vision adds real value, when it''s expensive theater, and how to route by document type instead of treating everything the same.","isNew":false,"isUpd":false,"estMin":40}]'::jsonb)
  on conflict (course_id, id) do update set tier = excluded.tier, data = excluded.data, updated_at = now();
insert into public.content (course_id, id, tier, data) values ('ai-eng', 'glossary', 'public', '[["LLM (Large Language Model)","The AI engine behind ChatGPT, Claude, and Gemini, a program trained on enormous amounts of text to predict the next word, which turns out to make it capable of writing, reasoning, and coding.","llm"],["Token","The chunk of text a model actually processes, roughly ¾ of a word in English. Everything (price, limits, speed) is measured in tokens.","llm"],["Context window","The maximum amount of text a model can see in one request, its working memory. Everything you want it to know right now must fit here.","context"],["Prompt","The text you send to the model: instructions, examples, background, and the actual question.","prompt"],["System prompt","The standing instructions that define the AI''s role and rules, set by the developer and weighted heavily by the model.","prompt"],["Completion / response","The text the model sends back.","llm"],["Inference","Running a trained model to get answers (as opposed to training it). When you call an API, you''re doing inference.","llm"],["Training","The months-long, GPU-heavy process where a model learns from data. As an AI engineer you almost never do this, you use models others trained.","llm"],["Fine-tuning","Additional training on your own examples to specialize a model. Powerful but often unnecessary, prompting and RAG usually get there first.","landscape"],["Parameters / weights","The billions of numbers inside a model that store what it learned. ''Open weights'' means these are downloadable so you can run the model yourself.","landscape"],["Temperature","A dial for randomness: 0 = consistent and boring, higher = varied and creative. Doesn''t guarantee identical outputs even at 0.","llm"],["Hallucination","When a model confidently states something false, invented facts, fake citations. Intrinsic to how LLMs work; managed with systems, not scolding.","halluc"],["RAG (Retrieval-Augmented Generation)","Looking up relevant passages from your documents and including them in the prompt so the model answers from your material, with citations.","rag"],["Embedding","Text converted to a list of numbers such that similar meanings produce similar numbers, the math behind search-by-meaning.","embed"],["Vector","That list of numbers. ''Vector search'' = finding the nearest vectors to your query''s vector.","embed"],["Vector database","A search engine specialized in finding similar vectors among millions, fast.","vecdb"],["Chunk / chunking","Splitting documents into passage-sized pieces before embedding them, so search can find the relevant paragraph instead of the whole file.","rag"],["Reranking","A second, more careful pass that re-sorts the top search results so the best few go to the model. Cheap and very effective.","rag"],["BM25 / keyword search","Classic exact-word search. Complements vector search, which can miss exact codes and names.","rag"],["Hybrid search","Using keyword AND vector search together, the production default.","rag"],["Agent","An AI that takes multi-step actions using tools to pursue a goal, deciding its own path as it goes.","agents"],["Workflow","A fixed sequence of steps with AI calls inside, the simpler, cheaper alternative to an agent when the path is known in advance.","agents"],["Tool / function calling","The mechanism letting a model request actions (search, send, look up) that YOUR code then executes. The model asks; your code acts.","tools"],["MCP (Model Context Protocol)","The industry-standard way to expose tools to any AI app, write the integration once, every assistant can use it.","tools"],["Harness","All the software wrapped around the model in an agent system: context management, tool registry, safety gates, progress tracking. Where reliability comes from.","harness"],["Compaction","Summarizing older conversation history to free up context window space. Lossy, important state must be saved elsewhere.","context"],["Sub-agent","A helper AI spawned with a fresh context to do one noisy task (like a big search) and report back just the conclusion.","multi"],["Orchestrator","The lead agent in a multi-agent system: breaks down the task, briefs workers, assembles results.","multi"],["Eval","An automated quality test for AI: a set of inputs with known good outcomes, scored on every change. The AI equivalent of a test suite.","evals"],["Golden set / golden dataset","Your curated collection of real test cases, the fixture library your evals run against.","evals"],["LLM-as-judge","Using one AI model to grade another''s answers against a rubric. Standard practice, with rules to keep it honest.","evals"],["Guardrail","An automated check on what goes into or comes out of the model: blocking attacks, redacting personal data, validating answers.","halluc"],["Prompt injection","An attack where malicious instructions are hidden inside content the AI reads (an email, a webpage) to hijack its behavior.","halluc"],["Grounding","Forcing answers to be based on provided sources rather than the model''s general memory, usually with citations.","halluc"],["Faithfulness","Whether an answer''s claims are actually supported by the sources it cites. Checked automatically in serious systems.","halluc"],["Gateway","A single routing layer all AI traffic flows through, enabling fallbacks, cost tracking, caching, and easy model swaps.","design"],["Prompt caching","Provider feature that makes repeated prompt prefixes (like your system prompt) up to 90% cheaper.","llm"],["Batch API","Half-price processing for work that can wait hours instead of seconds, bulk jobs, nightly evals.","design"],["Streaming","Sending the answer word-by-word as it''s generated, so users see progress immediately.","llm"],["TTFT (time to first token)","How long before the first word of the answer appears, the latency users feel most.","llm"],["Open weights","Models whose internals are downloadable (Llama, DeepSeek, Qwen) so you can run them on your own hardware, cheaper at scale, more work.","landscape"],["Reasoning model / mode","A model that ''thinks'' through hidden working steps before answering, better on hard problems, slower and pricier.","llm"],["Structured output","Forcing the model''s answer into an exact format (like JSON matching a schema) so software can parse it reliably.","prompt"],["Few-shot","Including a few worked examples in the prompt so the model copies the pattern. Usually beats lengthy instructions.","prompt"],["Semantic cache","Recognizing that a new question is a rephrase of one you''ve answered before, and reusing the answer instead of paying for a new one.","design"],["Multi-agent system","Several AI agents cooperating on one task, usually one orchestrator plus parallel workers.","multi"],["GPU","The hardware AI models run on. Relevant to you mainly if you self-host open-weight models.","landscape"],["API / SDK","API: the web interface you call to use a model. SDK: the code library that makes calling it convenient.","llm"]]'::jsonb)
  on conflict (course_id, id) do update set tier = excluded.tier, data = excluded.data, updated_at = now();
insert into public.content (course_id, id, tier, data) values ('ai-eng', 'plain', 'public', '{"llm":"An LLM (large language model) is a program that''s extremely good at predicting the next word. You send it text, it sends text back, and that''s the whole interaction. It doesn''t remember you between calls, it isn''t wired into anything, and it sometimes gets things wrong while sounding completely sure of itself. This module is about that text-in/text-out machine: what it costs, how fast it is, and how to pick the right one.","prompt":"A prompt is the text you send to the model: your instructions plus whatever the user asked. Writing a good one is like briefing a very capable temp worker who has never seen your company before. Clear rules, a few examples, and a defined output format change everything. This module is about doing that systematically instead of by trial and error.","context":"The ''context window'' is everything the model can see right now. Think of it as the model''s desk: anything not on the desk doesn''t exist to it. This module is about deciding what goes on that desk, which documents, how much chat history, and what to summarize away once it fills up. It sounds mundane. It''s actually most of the job.","landscape":"There are a handful of major AI models, from Anthropic, OpenAI, Google, and others. They leapfrog each other every few months and vary enormously in price. This module covers who the players are right now and, more durably, how to choose between them without getting swept up in launch-day hype.","rag":"RAG (retrieval-augmented generation) means that before the model answers, your system looks up relevant passages from YOUR documents and pastes them into the prompt. The model then answers from your material instead of its general memory. This is how you build an AI that knows your company''s docs, policies, or products, and can cite where each answer came from.","embed":"An embedding turns a piece of text into a long list of numbers, designed so that texts with similar MEANING get similar numbers. That lets a computer measure ''how alike are these two sentences?'' mathematically, which is the trick underneath search-by-meaning, recommendations, and most of RAG. This module explains how that works and where it breaks.","vecdb":"Once you''ve turned millions of text snippets into number-lists (embeddings), you need a way to find the closest matches to a question in milliseconds. A vector database is a search engine built for exactly that. This module covers how they work, when you need a dedicated one, and when a regular database does the job fine.","memory":"Out of the box, an AI assistant forgets everything the moment a conversation ends. Any product where it ''remembers'' you (your preferences, past conversations, ongoing projects) has an engineered memory system behind it: code that decides what to save, where, and what to bring back later. This module is how those systems are built and how they go wrong.","agents":"An agent is an AI that acts instead of just answering. It can search, read files, call APIs, and take several steps toward a goal, deciding what to do as it goes. That autonomy cuts both ways. Tiny per-step error rates snowball across many steps. This module covers when agents earn their keep and what makes them reliable.","tools":"Tools are how an AI gets things done in the world. You describe a set of actions to the model (''search_flights'', ''send_email''), like buttons with documentation, and the model asks your code to press them. The model never runs anything itself. It requests, and your code decides. Designing those buttons well matters more than almost anything else in agent quality.","harness":"If the model is an engine, the harness is the rest of the car: steering, brakes, dashboard, seatbelts. It''s all the software wrapped around the model in an agent system. What the model sees each turn, which tools it gets, when a human has to approve, how progress survives a crash. Same engine, different car, wildly different results. That''s why this layer is where AI engineering happens in 2026.","multi":"Sometimes one AI splits work across several AIs: one coordinating, others researching different subtopics in parallel, each with its own working memory. Like hiring a team instead of a single person, it pays off for genuinely parallel work and just adds cost and miscommunication everywhere else. This module is about telling those situations apart.","design":"A working AI demo and a reliable AI product are separated by a lot of unglamorous plumbing. What happens when the AI provider goes down? How do you stop costs from exploding? How do you notice quality dropped before customers do? This module is that plumbing: the production engineering around the model call.","evals":"You can''t test AI like normal code. The same input can produce different outputs, and ''correct'' is often a judgment call. Evals are the answer: a curated set of test questions with known good answers, run automatically against every change, so you KNOW whether the new version is better instead of feeling it. No single discipline separates serious AI teams from everyone else more clearly than this one.","halluc":"AI models sometimes state false things with total confidence: invented facts, fake citations, wrong numbers. This isn''t a bug to be patched. It''s a side effect of how they work, since they''re trained to sound plausible rather than to be true. This module covers the systems built around the model to catch fabrications before users see them, plus the related attack where someone hides malicious instructions in content the AI reads.","lead":"Past a certain level, your value isn''t writing the code. It''s making the calls: build it or buy it, which risks are acceptable, what to tell executives, how to keep a team''s skills current in a field that reinvents itself quarterly. This module is the judgment layer on top of everything technical you''ve learned.","finetune":"Fine-tuning is additional training that specializes a model on your data. Done right, it can slash inference costs and tighten consistency on narrow tasks. It''s also expensive, it can quietly break things the model used to handle well, and it''s almost never the first tool to reach for. This module covers when the economics actually work, how to run the training without contaminating your results, and how to verify you haven''t traded one problem for three others.","aisec":"Every AI feature you ship is a new attack surface. Users can hide instructions inside documents, emails, and web pages that hijack what your model does, and unlike traditional security bugs, these attacks turn the model''s own intelligence against you. This module covers the specific threat classes that LLM-powered systems face, how to design systems that hold under adversarial pressure, and which security controls actually work versus the ones that look good on paper and fail in an afternoon.","mlops":"An AI system that works in demos can be quietly failing in production: returning wrong answers that look right, degrading week by week as the model drifts, running up costs with no alerts. Standard infrastructure dashboards can''t see any of it. This module covers the extra instrumentation layer AI systems need, namely distributed traces with AI-specific attributes, quality metrics on live traffic, and the drift alerts that catch problems before users do.","dataeng":"The retrieval system is only as good as the data pipeline feeding it. Bad chunking, stale indexes, mixed embedding versions, and missing access control propagation quietly cap quality at 60–70% before you write a single prompt. This module covers how to design the pipeline so the retrieval system improves automatically, with the quality ceiling set by the content rather than the plumbing.","multimodal":"Not all documents are text. Scanned PDFs, tables, charts, and audio recordings carry information that text-only pipelines miss entirely, but routing everything through an expensive vision model is a fast way to a very large bill. This module covers when vision or audio processing actually adds value, when it''s just expensive theater, and how to build routing logic that sends each document type through the right pipeline at the right cost."}'::jsonb)
  on conflict (course_id, id) do update set tier = excluded.tier, data = excluded.data, updated_at = now();
insert into public.content (course_id, id, tier, data) values ('ai-eng', 'videos', 'public', '{"llm":{"src":"llm/preface.mp4","poster":"llm/preface.jpg","vtt":"llm/preface.en.vtt","duration":41,"tier":"public","title":"What an LLM actually is","caption":"A short preface — what an LLM really is, before the cost, latency, and model-choice details."},"prompt":{"src":"prompt/preface.mp4","poster":"prompt/preface.jpg","vtt":"prompt/preface.en.vtt","duration":48,"tier":"public","title":"The cheapest quality lever you own","caption":"A short preface — why prompting is the first lever to pull, before the techniques."},"context":{"src":"context/preface.mp4","poster":"context/preface.jpg","vtt":"context/preface.en.vtt","duration":41,"tier":"public","title":"Curating what the model sees","caption":"A short preface — why what the model sees matters more than how you phrase it."},"landscape":{"src":"landscape/preface.mp4","poster":"landscape/preface.jpg","vtt":"landscape/preface.en.vtt","duration":44,"tier":"public","title":"How to choose, when the lineup keeps changing","caption":"A short preface — how to choose a model in a lineup that changes every quarter."},"rag":{"src":"rag/preface.mp4","poster":"rag/preface.jpg","vtt":"rag/preface.en.vtt","duration":54,"tier":"public","title":"Why retrieval beats a bigger prompt","caption":"A short preface — the problem RAG actually solves, before we get into how it works."},"embed":{"src":"embed/preface.mp4","poster":"embed/preface.jpg","vtt":"embed/preface.en.vtt","duration":49,"tier":"public","title":"Meaning as geometry","caption":"A short preface — the intuition behind meaning-as-geometry, before the engineering."},"vecdb":{"src":"vecdb/preface.mp4","poster":"vecdb/preface.jpg","vtt":"vecdb/preface.en.vtt","duration":44,"tier":"public","title":"A search index, not a database of record","caption":"A short preface — what a vector database really is, and when you need one."},"memory":{"src":"memory/preface.mp4","poster":"memory/preface.jpg","vtt":"memory/preface.en.vtt","duration":37,"tier":"public","title":"State across the stateless","caption":"A short preface — why remembering is a write-path problem you engineer."},"agents":{"src":"agents/preface.mp4","poster":"agents/preface.jpg","vtt":"agents/preface.en.vtt","duration":39,"tier":"public","title":"An LLM in a loop","caption":"A short preface — what an agent is, and why reliability comes from the loop."},"tools":{"src":"tools/preface.mp4","poster":"tools/preface.jpg","vtt":"tools/preface.en.vtt","duration":39,"tier":"public","title":"The hands of the model","caption":"A short preface — why most agent bugs are really tool-design bugs."},"harness":{"src":"harness/preface.mp4","poster":"harness/preface.jpg","vtt":"harness/preface.en.vtt","duration":43,"tier":"public","title":"Where capability actually comes from","caption":"A short preface — why the harness, not the model, is where capability lives."},"multi":{"src":"multi/preface.mp4","poster":"multi/preface.jpg","vtt":"multi/preface.en.vtt","duration":40,"tier":"public","title":"An org chart for context windows","caption":"A short preface — when adding more agents pays off, and when it just adds cost."},"design":{"src":"design/preface.mp4","poster":"design/preface.jpg","vtt":"design/preface.en.vtt","duration":44,"tier":"public","title":"The model call is 5% of the system","caption":"A short preface — why the model call is only 5% of a real AI system."},"evals":{"src":"evals/preface.mp4","poster":"evals/preface.jpg","vtt":"evals/preface.en.vtt","duration":41,"tier":"public","title":"Shipping, not guessing","caption":"A short preface — why evals are what separate shipping from guessing."},"halluc":{"src":"halluc/preface.mp4","poster":"halluc/preface.jpg","vtt":"halluc/preface.en.vtt","duration":44,"tier":"public","title":"Engineering around confidently wrong","caption":"A short preface — why hallucination is intrinsic, and how to engineer around it."},"lead":{"src":"lead/preface.mp4","poster":"lead/preface.jpg","vtt":"lead/preface.en.vtt","duration":46,"tier":"public","title":"The judgment layer","caption":"A short preface — the judgment layer that matters past senior level."},"finetune":{"src":"finetune/preface.mp4","poster":"finetune/preface.jpg","vtt":"finetune/preface.en.vtt","duration":44,"tier":"public","title":"Surgery versus clothing","caption":"A short preface — when reshaping weights beats reshaping prompts."},"aisec":{"src":"aisec/preface.mp4","poster":"aisec/preface.jpg","vtt":"aisec/preface.en.vtt","duration":41,"tier":"public","title":"A new attack surface","caption":"A short preface — why every AI feature is a new attack surface."},"mlops":{"src":"mlops/preface.mp4","poster":"mlops/preface.jpg","vtt":"mlops/preface.en.vtt","duration":40,"tier":"public","title":"AI systems fail silently","caption":"A short preface — why AI systems fail silently, and what to instrument first."},"dataeng":{"src":"dataeng/preface.mp4","poster":"dataeng/preface.jpg","vtt":"dataeng/preface.en.vtt","duration":42,"tier":"public","title":"The invisible quality ceiling","caption":"A short preface — why the data pipeline sets your retrieval ceiling."},"multimodal":{"src":"multimodal/preface.mp4","poster":"multimodal/preface.jpg","vtt":"multimodal/preface.en.vtt","duration":42,"tier":"public","title":"When vision earns its cost","caption":"A short preface — when vision earns its cost, and when to skip it."}}'::jsonb)
